import { exhausted, nextDelayMs } from "./retry.js";
import { park } from "./deadletter.js";

export interface Delivery {
  id: string;
  endpoint: string;
  payload: string;
  attempt: number;
}

export interface DispatchDeps {
  post(endpoint: string, body: string): Promise<{ ok: boolean; status: number }>;
  requeue(delivery: Delivery, delayMs: number): Promise<void>;
}

export async function dispatch(delivery: Delivery, deps: DispatchDeps): Promise<boolean> {
  const response = await deps.post(delivery.endpoint, delivery.payload);
  if (response.ok) return true;
  if (exhausted(delivery.attempt)) {
    park({ deliveryId: delivery.id, failedAt: Date.now(), lastError: `http ${response.status}` });
    return false;
  }
  await deps.requeue(delivery, nextDelayMs(delivery.attempt));
  return false;
}

