const BASE_DELAY_MS = 250;
const MAX_DELAY_MS = 60_000;
const DEFAULT_BUDGET = 8;

/** Exponential backoff with full jitter, capped so one dead endpoint cannot park a worker. */
export function nextDelayMs(attempt: number, random = Math.random): number {
  const ceiling = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * 2 ** attempt);
  return Math.floor(random() * ceiling);
}

export function exhausted(attempt: number, budget = DEFAULT_BUDGET): boolean {
  return attempt >= budget;
}

