export interface DeadLetter {
  deliveryId: string;
  failedAt: number;
  lastError: string;
}

const parked: DeadLetter[] = [];

export function park(entry: DeadLetter): DeadLetter {
  parked.push(entry);
  return entry;
}

export function list(): readonly DeadLetter[] {
  return parked;
}

